  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "动机、前向函数、输入输出以及模块模式、记录状态、推理上下文、数值策略和请求状态的身份已明确；修订正确地把 T 从根标志扩展为相关模块配置。",
      "evidence": [
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "这里 `T` 不是根模块的一个布尔值，而是相关模块的模式配置：`T = (t_m)_{m∈M_sens}`"
        },
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "`G` 表示自动微分记录，`I` 表示推理区域深度。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "完整模式清单、统一与显式混合模式、运行期间修改边界均已交付，原 MODULE-MODE 问题关闭。普通存储转换的上下文前提和仅后处理求导与穿过模型求导的区别也已正确声明；剩余缺口在执行顺序与失败生命周期。",
      "evidence": [
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "两种方式都不能只检查根模块。"
        },
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "需要穿过模型求导：必须让模型 forward 处于 record 路径；推理区域已经省略了前向图和保存量，事后 materialize 不能恢复它。"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "先退出本次推理区域、检查外层上下文、创建独立普通存储的主要修复成立。但异步复制只记录完成事件，紧接着的消费者校验却要求事件已完成，没有等待或 Pending 后继；复制提交后的异常清理也未保护已在途的源和目标。因此转换算法尚未形成完整合法路径。",
      "evidence": [
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "event = RecordCompletion(stream, out)"
        },
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "require t.copy_event is completed before consumption"
        },
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "catch error:\n      Release(out)\n      raise error"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "原 SAVED-STORAGE-BOUND 的逻辑元素上界错误已修复：逻辑载荷明确不代表物理驻留，提供小切片与共享视图反例，64 MiB/768 MiB 算例声明独立紧凑存储和同时存活条件。计算、流量、同步关键路径、准备和驻留成本均有条件化解释。P_peak 的使用须随 r_s 的计量口径解释；选择下界计量时只能得到对应下界。",
      "evidence": [
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "它不是底层存储驻留、实际设备容量或真实节省的上界。"
        },
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "若 12 个类似激活各自拥有独立连续存储、同时存活，数据为 `768 MiB`"
        },
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "这是明确设定的解析算例，不是设备实测；吞吐场景中其他请求可能填满空洞，不能用这个单请求数替代吞吐结论。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "模式、梯度范围、shape、数值策略、并发和 stream 条件变化都有保留对象、调整项和放弃条件。需要修补的是既有异步转换机制，而不是增加新的条件变化清单。",
      "evidence": [
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "若只做后处理，退出推理上下文后建立普通输出；若穿过模型，放弃局部推理区域，改 record"
        },
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "应改用 no_grad 或普通记录路径，而不是在边界处静默复制一次并假设所有别名和图问题都消失。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "partial",
      "reason": "竞争解释与区分干预充分，模式与共享存储负对照确实针对旧缺陷。但转换检查没有实现正文要求的完成事件 oracle：脚本直接赋予 copy-complete，消费者完全不读取该字段，也不覆盖复制已提交后的异常。已有 PASS 无法发现本轮剩余算法缺口。",
      "evidence": [
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "consumer oracle 必须用 is_inference、存储身份和完成事件拒绝它。"
        },
        {
          "path": "knowledge/frameworks/inference-eval.md",
          "quote": "测试要能区分“外层上下文未退出”和“复制动作失败”。"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-FW-001-AUTOGRAD-MATERIALIZE",
      "criterion": "algorithm",
      "evidence": "MaterializeOutsideInference 执行「event = RecordCompletion(stream, out)」后返回；ServeOne 随即执行「ValidateConsumer(z, q.grad_scope)」，其条件为「require t.copy_event is completed before consumption」，而 PublishAfterCompletion 位于校验之后。脚本 materialize_outside_inference 直接构造 copy_event='copy-complete'，validate_consumer 不读取 copy_event。",
      "impact": "记录事件不代表复制已经完成。正常异步转换可以返回尚未完成的事件，随后校验立即失败，算法没有等待、挂起或完成后继续的路径。no_grad 产生的普通 raw 又没有明确建立消费者所要求的 copy_event。脚本对 pending 或缺失事件的普通张量仍会放行，无法检验正文声称的完成条件。",
      "blocking": true,
      "required_revision": "明确 forward、复制及消费的执行 stream 和生产者依赖。选择等待完成后校验，或进入 Pending 并在完成后继续，或明确建立消费者 stream 的等待依赖并据此定义 oracle。为 no_grad 普通输出定义相应就绪凭据。检查模型必须具有实际可推进的 pending/completed 状态，并用同一 oracle 拒绝未建立合法依赖的提前消费；不得由转换函数无条件宣布 copy-complete。保留已正确修复的外层上下文拒绝、普通存储创建和梯度范围区分。"
    },
    {
      "id": "K-FW-001-MATERIALIZE-FAILURE-LIFETIME",
      "criterion": "algorithm",
      "evidence": "MaterializeOutsideInference 的顺序为「CopyData(out, raw)」「event = RecordCompletion(stream, out)」；异常分支立即「Release(out)」「raise error」。源保护「raw.keep_alive_until = event」只在整个 try 成功后建立。ServeOne 对转换和消费者校验没有对应的失败收尾分支。",
      "impact": "若复制已经入队，而完成事件登记或后续主机步骤失败，异常分支没有证明在途访问已经结束，也没有把源和目标交给受保护的延迟回收者。按算法当前定义，释放目标和栈展开释放源可能早于物理最后使用；同时请求可能停留在前向成功后的非终态。PopMode 的 finally 只恢复上下文，不能解决这些责任。",
      "blocking": true,
      "required_revision": "在任何异步提交前取得源和目标的生命周期保护。失败后明确选择排空相关 stream、按已有依赖延迟回收，或隔离无法确认完成的执行域，之后才允许复用。将转换、校验和发布前失败纳入请求失败收尾，保证输出不可见且终态明确。补充复制已入队但事件登记失败的受控抽象轨迹，检查非提交与物理可回收是两个不同条件；若依赖框架的 stream-ordered Release，必须明确其保证及源的保护方式。"
    }
  ],
  "limitations": [
    "S-TORCH-INFERENCE 仅提供来源说明和固定提交身份，没有供给可读原始文档或源码；本审查不声称完成其上游原文或具体转换 API 核验。",
    "检查是 CPU 抽象状态模型；目标 PyTorch 张量行为、CUDA stream、allocator、数值误差、性能和服务尾延迟均无本轮设备验证。",
    "P_peak 需固定分配身份和 r_s 的计量口径；使用存储区间下界时不能把结果当作实际物理容量测量。",
    "docs/knowledge-build-workflow.md 未包含在供给材料中，本环境也没有可用的文件读取工具；输出采用用户明确提供的 review JSON schema。链接仅核对了供给内容中的相对路径关系，未执行磁盘存在性检查。"
  ],
  "checks": [
    {
      "script": "tools/check_k_fw_001_full.py",
      "args": []
    }
  ],
  "no_checks_reason": "",
  "reading_scope": "本审查完整阅读了用户供给的候选正文、完整检查脚本、author_notes 和 actual_preflight 执行记录。以下范围均为供给材料声明的 extracted text 零基半开字符范围，结论限于实际暴露文本，不扩展为上游仓库完整阅读：AGENTS.md full [0,567)；docs/knowledge-method.md full [0,2251)；docs/knowledge-review.md full [0,3016)；knowledge/frameworks/inference-eval.md full [0,15652)；knowledge/sources/S-TORCH-INFERENCE.md full [0,727)；S-TORCH-CUDA.md full [0,1468)；S-TORCH-REPRO.md full [0,501)；S-TORCH-DYNAMIC.md full [0,550)；S-TORCH-NUMERIC.md full [0,532)；knowledge/frameworks/numerical-reference.md full [0,3374)；compile-dynamic-shapes.md full [0,4495)；knowledge/system-semantics/position-mask-cache.md full [0,4078)；knowledge/frameworks/checkpoint-loading.md full [0,3354)；knowledge/system-semantics/host-runtime.md full [0,7559)；knowledge/tools/correctness-oracles.md full [0,5245)；knowledge/system-semantics/memory-allocators.md full [0,4191)；knowledge/hardware/cpu-serving.md full [0,3694)；knowledge/tools/framework-profiler-scope.md full [0,4833)。knowledge/algorithms/operator-primitives.md 仅阅读供给摘录 [0,2566) 与 [4000,9934)，未列入 documents。四份来源全文按供给 full 范围阅读：references/S-TORCH-CUDA/fulltext.txt [0,80851)、S-TORCH-REPRO/fulltext.txt [0,7936)、S-TORCH-DYNAMIC/fulltext.txt [0,11742)、S-TORCH-NUMERIC/fulltext.txt [0,10998)。tools/check_k_fw_001_full.py 阅读完整 candidate.test_script，身份采用本轮指定哈希。未读取源码归档、S-TORCH-INFERENCE 上游原文、未供给的历史 review 或 workflow 文件。documents 的字节身份按用户要求原样绑定，未声称重新计算本地哈希。",
  "test_assessment": "供给 actual_preflight 显示绑定脚本在 remote_bwrap 中以 Python 3.12 执行，returncode=0，RESULT: PASS；本次 reviewer 没有可用 Python/终端工具，未独立重跑，也未把其他检查记为 PASS。逐行审查表明：模式清单以冻结 spec 为预期，子模块突变后完整清单拒绝而根检查接受，另有合法混合模式正例，能辨别原 MODULE-MODE 缺陷。存储检查具有可手算的独立容量预期，覆盖独立紧凑存储、小切片和共享完整视图，并暴露按视图累加的重复计费。转换检查采用声明清楚的抽象创建规则，能区分外层推理上下文和 inference 张量来源，也能拒绝没有模型图的物化结果；这些只支持抽象语义，不能作为 PyTorch 实测。关键遗漏是事件始终被直接设成 copy-complete，validate_consumer 只检查 is_inference、origin 或 model_graph，未检查 copy_event；按当前函数逐句推演，一个 is_inference=False、origin='materialized_after_inference'、copy_event=None 或 pending 的状态仍会返回 True，此推演不是新增执行结果。脚本也没有复制提交、事件登记失败、延迟回收或完整 ServeOne 轨迹，因而无法发现立即校验尚未完成事件和异常路径提前释放的问题。线程检查仅覆盖单个上下文的嵌套及 finally 恢复；请求随机流、真实多线程、数值、编译和设备诊断均未执行。作者关于未做 PyTorch/GPU 实测的边界正确，但这些边界不能替代对已交付异步算法及其抽象 oracle 的修复。"
}
